INSERT INTO `experience_reviews` (`id`, `order_item_id`, `experience_id`, `member_id`, `rating`, `comment`, `created_at`, `image_url`) VALUES
(1, 253, 1, 1, 5, '一開始擔心自然光會跟不上，結果說明得很清楚，整個過程很安心。 現場節奏舒服，拍照和休息的時間都恰到好處。 回住宿處後還覺得這段安排很值得。', '2026-07-02 11:07:00', NULL),
(2, 353, 1, 2, 4, '取景位置安排得很剛好，不會太匆忙，也不會讓人一直空等。 朋友一直說這樣安排比自己查資料有效率。 搭車回程時還覺得這段安排很值得。', '2026-07-05 12:18:00', NULL),
(3, 453, 1, 3, 5, '因為姿勢引導做得細心，同行的家人也能輕鬆跟上。 結束時大家都還意猶未盡，氣氛真的很好。 整理照片時還覺得這段安排很值得。', '2026-07-08 13:29:00', NULL),
(4, 553, 1, 4, 5, '我很喜歡街景背景這一段，感覺不是走馬看花，而是真的有收穫。 有問題時得到的回答很實在，不會只講表面的內容。 晚餐聊天時還覺得這段安排很值得。', '2026-07-11 14:40:00', NULL),
(5, 653, 1, 5, 4, '原本只是抱著試試看的心情來，沒想到拍照節奏比預期更有意思。 還好有先預約，不然自己來大概會錯過不少內容。 隔天回想起來還覺得這段安排很值得。', '2026-07-14 15:51:00', NULL),
(6, 753, 1, 6, 5, '從構圖建議可以感覺到帶領者很熟悉現場，遇到問題也處理得很自然。 回去整理照片時，又想起不少剛剛聽到的小故事。 走到下一站前還覺得這段安排很值得。', '2026-07-17 16:02:00', NULL),
(7, 853, 1, 7, 4, '互動畫面的細節很貼心，讓原本有點緊張的我很快放鬆下來。 整體沒有硬推銷的感覺，讓人可以專心享受當下。 休息的時候還覺得這段安排很值得。', '2026-07-20 17:13:00', NULL),
(8, 953, 1, 8, 5, '如果時間有限，我覺得成品色調特別值得保留，內容很精簡卻不單薄。 不需要準備很多背景知識，也能聽得很投入。 回家之後還覺得這段安排很值得。', '2026-07-23 18:24:00', NULL),
(9, 253, 1, 9, 5, '結束後還在回想服裝建議的部分，這趟行程裡算是很有記憶點的一段。 如果下次再來，我會想帶不同的朋友一起參加。 和家人分享時還覺得這段安排很值得。', '2026-07-26 19:35:00', NULL),
(10, 353, 1, 10, 4, '最讓我印象深刻的是拍攝路線，原本沒注意到的地方都被點出來了。 帶領方式很自然，像是跟熟悉當地的朋友一起出門。 離開後還覺得這段安排很值得。', '2026-07-29 10:46:00', NULL),
(11, 254, 2, 8, 5, '作品細節安排得很剛好，不會太匆忙，也不會讓人一直空等。 帶領方式很自然，像是跟熟悉當地的朋友一起出門。 搭車回程時還覺得這段安排很值得。', '2026-07-03 12:14:00', NULL),
(12, 354, 2, 9, 4, '因為時代背景做得細心，同行的家人也能輕鬆跟上。 現場節奏舒服，拍照和休息的時間都恰到好處。 整理照片時還覺得這段安排很值得。', '2026-07-06 13:25:00', NULL),
(13, 454, 2, 10, 5, '我很喜歡畫面構圖這一段，感覺不是走馬看花，而是真的有收穫。 朋友一直說這樣安排比自己查資料有效率。 晚餐聊天時還覺得這段安排很值得。', '2026-07-09 14:36:00', NULL),
(14, 554, 2, 11, 5, '原本只是抱著試試看的心情來，沒想到策展脈絡比預期更有意思。 結束時大家都還意猶未盡，氣氛真的很好。 隔天回想起來還覺得這段安排很值得。', '2026-07-12 15:47:00', NULL),
(15, 654, 2, 12, 4, '從作者故事可以感覺到帶領者很熟悉現場，遇到問題也處理得很自然。 有問題時得到的回答很實在，不會只講表面的內容。 走到下一站前還覺得這段安排很值得。', '2026-07-15 16:58:00', NULL),
(16, 754, 2, 13, 5, '館藏亮點的細節很貼心，讓原本有點緊張的我很快放鬆下來。 還好有先預約，不然自己來大概會錯過不少內容。 休息的時候還覺得這段安排很值得。', '2026-07-18 17:09:00', NULL),
(17, 854, 2, 14, 4, '如果時間有限，我覺得空間設計特別值得保留，內容很精簡卻不單薄。 回去整理照片時，又想起不少剛剛聽到的小故事。 回家之後還覺得這段安排很值得。', '2026-07-21 18:20:00', NULL),
(18, 954, 2, 15, 5, '結束後還在回想欣賞角度的部分，這趟行程裡算是很有記憶點的一段。 整體沒有硬推銷的感覺，讓人可以專心享受當下。 和家人分享時還覺得這段安排很值得。', '2026-07-24 19:31:00', NULL),
(19, 254, 2, 16, 5, '最讓我印象深刻的是解說節奏，原本沒注意到的地方都被點出來了。 不需要準備很多背景知識，也能聽得很投入。 離開後還覺得這段安排很值得。', '2026-07-27 10:42:00', NULL),
(20, 354, 2, 17, 4, '一開始擔心提問時間會跟不上，結果說明得很清楚，整個過程很安心。 如果下次再來，我會想帶不同的朋友一起參加。 回住宿處後還覺得這段安排很值得。', '2026-07-01 11:53:00', NULL),
(21, 255, 3, 15, 5, '因為備料順序做得細心，同行的家人也能輕鬆跟上。 如果下次再來，我會想帶不同的朋友一起參加。 整理照片時還覺得這段安排很值得。', '2026-07-04 13:21:00', NULL),
(22, 355, 3, 16, 4, '我很喜歡火候掌握這一段，感覺不是走馬看花，而是真的有收穫。 帶領方式很自然，像是跟熟悉當地的朋友一起出門。 晚餐聊天時還覺得這段安排很值得。', '2026-07-07 14:32:00', NULL),
(23, 455, 3, 17, 5, '原本只是抱著試試看的心情來，沒想到香料搭配比預期更有意思。 現場節奏舒服，拍照和休息的時間都恰到好處。 隔天回想起來還覺得這段安排很值得。', '2026-07-10 15:43:00', NULL),
(24, 555, 3, 18, 5, '從調味方式可以感覺到帶領者很熟悉現場，遇到問題也處理得很自然。 朋友一直說這樣安排比自己查資料有效率。 走到下一站前還覺得這段安排很值得。', '2026-07-13 16:54:00', NULL),
(25, 655, 3, 19, 4, '手作步驟的細節很貼心，讓原本有點緊張的我很快放鬆下來。 結束時大家都還意猶未盡，氣氛真的很好。 休息的時候還覺得這段安排很值得。', '2026-07-16 17:05:00', NULL),
(26, 755, 3, 20, 5, '如果時間有限，我覺得擺盤技巧特別值得保留，內容很精簡卻不單薄。 有問題時得到的回答很實在，不會只講表面的內容。 回家之後還覺得這段安排很值得。', '2026-07-19 18:16:00', NULL),
(27, 855, 3, 21, 4, '結束後還在回想食材介紹的部分，這趟行程裡算是很有記憶點的一段。 還好有先預約，不然自己來大概會錯過不少內容。 和家人分享時還覺得這段安排很值得。', '2026-07-22 19:27:00', NULL),
(28, 955, 3, 22, 5, '最讓我印象深刻的是操作時間，原本沒注意到的地方都被點出來了。 回去整理照片時，又想起不少剛剛聽到的小故事。 離開後還覺得這段安排很值得。', '2026-07-25 10:38:00', NULL),
(29, 255, 3, 23, 5, '一開始擔心成品分享會跟不上，結果說明得很清楚，整個過程很安心。 整體沒有硬推銷的感覺，讓人可以專心享受當下。 回住宿處後還覺得這段安排很值得。', '2026-07-28 11:49:00', NULL),
